import React from "react";
import { Link, useLocation } from "react-router-dom";
import "./Navbar.css";
import logo from"../assets/Logo.png";
function Navbar() {
  const location = useLocation();

  return (
    <nav className="navbar">
      {/* شعار الموقع */}
      <div className="navbar-logo">
        <img src={logo} alt="Breast Cancer Logo" className="logo-img" />
        <span>Breast Cancer Detection</span>
      </div>

      {/* روابط الصفحات */}
      <div className="navbar-links">
        <Link
          to="/"
          className={`navbar-link ${
            location.pathname === "/" ? "active-link" : ""
          }`}
        >
          الرئيسية
        </Link>

        <Link
          to="/samples"
          className={`navbar-link ${
            location.pathname === "/samples" ? "active-link" : ""
          }`}
        >
          إدخال العينات
        </Link>

        <Link
          to="/features"
          className={`navbar-link ${
            location.pathname === "/features" ? "active-link" : ""
          }`}
        >
          إدخال الخصائص
        </Link>

        <Link
          to="/results"
          className={`navbar-link ${
            location.pathname === "/results" ? "active-link" : ""
          }`}
        >
          النتائج
        </Link>
      </div>

      {/* مساحة فارغة أو يمكنك وضع زر مستقبلاً */}
      <div className="navbar-empty"></div>
    </nav>
  );
}

export default Navbar;
